# Retire a person from a date (blank: the sheet's today). Once the sheet's today reaches that date
# their OPEN and PENDING claims count in no live total, unless a statement binds them.
validate:
  class: net.officefloor.hq.app.person.ValidateRetire
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: snapshot
# Keep the figures as they were, so the change can audit the ones it moves.
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: retire
retire:
  class: net.officefloor.hq.app.person.RetirePerson
  govern: [ transaction ]
  next: record
# Audit only once the retirement is saved.
record:
  class: net.officefloor.hq.app.person.RecordPersonRetired
  govern: [ transaction ]
  next: rollup
# After the change's own lines: a line per person whose figures moved, then the totals if they did.
rollup:
  class: net.officefloor.hq.app.rollup.RecordRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
  govern: [ transaction ]
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.hq.app.rollup.Actor;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateRetire {
    public void validate(@RequestBody RetireRequest request, Out<Retirement> body, Out<Actor> actor)
            throws InvalidSheetRequestException {
        Retirement retirement = checked(request);
        body.set(retirement);
        actor.set(new Actor(retirement.user()));
    }

    /** The retirement as typed, checked: a blank date is the sheet's today, anything else a date. */
    static Retirement checked(RetireRequest request) throws InvalidSheetRequestException {
        String raw = request == null || request.from() == null ? "" : request.from().trim();
        LocalDate from = null;
        if (!raw.isEmpty()) {
            try {
                from = LocalDate.parse(raw);
            } catch (DateTimeParseException e) {
                throw new InvalidSheetRequestException("Not a date (yyyy-mm-dd): " + raw);
            }
        }
        return new Retirement(from, request == null ? null : request.user());
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;

/** Retires the person from the date given, or the sheet's today. Not an edit: the person's
 *  version is untouched, so an editor open on them can still save. */
public class RetirePerson {
    public void retire(@Val Retirement retirement, @Val Person person, Sheets sheets, People people) {
        person.setRetiredFrom(retirement.from() != null ? retirement.from() : sheets.today(person.getSheetId()));
        people.saveRetirement(person);
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;

/** A checked retirement: the date retired from (null: the sheet's today) and by whom. */
public record Retirement(LocalDate from, String user) {
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;

/** Runs after the retirement is saved, so a refused one writes no audit line. */
public class RecordPersonRetired {
    public void record(@Val Retirement retirement, @Val Person person, Audit audit) {
        audit.record("PERSON_RETIRED sheet=" + person.getSheetId() + " by=" + retirement.user()
                + " name=" + person.getName() + " from=" + person.getRetiredFrom());
    }
}
package net.officefloor.hq.app.person;

/** Body of a retirement, as typed: the date retired from (blank for the sheet's today) and who
 *  makes the change. */
public record RetireRequest(String from, String user) {
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;

/** A claim dated after its person's retirement date; answered 409. */
public class PersonRetiredException extends Exception {
    public PersonRetiredException(String name, LocalDate from) {
        super(name + " is retired from " + from + ": no claim dated after it can be added");
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandlePersonRetired {
    public void handle(@Parameter PersonRetiredException ex,
            ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.CONFLICT));
    }
}
-- A person can be retired from a date. Set at all, they count as retired at once, whatever the
-- date: no claim dated after it can be added or edited for them, and the list hides them unless
-- retired people are shown. Their claims keep counting in every total.
ALTER TABLE person ADD COLUMN retired_from DATE;
