package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.List;

/** A person as the screen sees it, with their statement count, and the last statement's due-total
 *  (two decimals, null when it was n/a or none was taken) and date (yyyy-mm-dd, null when none was),
 *  and whether they are retired and from when (yyyy-mm-dd, null when not retired),
 *  and whether they have any hold and each hold's dates, and the ids of the people they have named as patrons. `grade` is
 *  the grade in force on the sheet's today; `grades` every grade recorded, by from-date (null: from
 *  the beginning of time, first); `terms` the person's own terms (null: none); `contact` their
 *  contact (null: none); `aliases` their aliases, sorted as names are compared; `clashing` whether
 *  their name or an alias is used on another sheet of their sheet's tree; `origin` the sheet they were
 *  transferred from (null: they were not). */
public record PersonResponse(long id, String name, String grade, int version, int statementCount,
        String statedTotal, String statementDate, boolean retired, String retiredFrom,
        boolean held, List<HoldDates> holds, List<Long> patrons, List<GradeFrom> grades, Integer terms,
        String contact, List<String> aliases, boolean clashing, String origin) {

    /** A hold's dates (yyyy-mm-dd; `to` null: open-ended). */
    public record HoldDates(String from, String to) {
    }

    public record GradeFrom(String grade, String from) {
    }

    public static PersonResponse from(Person person) {
        return new PersonResponse(person.getId(), person.getName(), person.getGrade(), person.getVersion(),
                person.getStatementCount(),
                person.getStatedTotal() != null ? person.getStatedTotal().toPlainString() : null,
                person.getStatementDate() != null ? person.getStatementDate().toString() : null,
                person.isRetired(), person.getRetiredFrom() != null ? person.getRetiredFrom().toString() : null,
                person.isHeld(),
                person.getHolds().stream()
                        .map(h -> new HoldDates(h.from().toString(), h.to() != null ? h.to().toString() : null))
                        .toList(),
                List.copyOf(person.getPatronIds()),
                person.getGrades().entrySet().stream()
                        .map(e -> new GradeFrom(e.getValue(), e.getKey().equals(LocalDate.MIN) ? null : e.getKey().toString()))
                        .toList(),
                person.getTerms(), person.getContact(), List.copyOf(person.getAliases()),
                person.isClashing(), person.getOriginSheet());
    }
}
package net.officefloor.hq.app.person;

import java.sql.Date;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** The people of each sheet, kept in list order: by position (a new person goes to the end). */
@Repository
public class People {

    private static final String COLUMNS = "SELECT id, sheet_id, name, grade, terms, contact, version, statement_count, stated_total, statement_date, retired_from, origin_sheet, origin_name, "
            + "(SELECT today FROM sheet WHERE sheet.id = person.sheet_id) AS sheet_today FROM person";

    /** The position after the last of the sheet (bound to the sheet id): a new person goes to the end. */
    static final String END_POSITION = "(SELECT COALESCE(MAX(position), 0) + 1 FROM person WHERE sheet_id = ?)";

    private final JdbcTemplate jdbc;

    public People(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public List<Person> onSheet(String sheetId) {
        List<Person> people = jdbc.query(COLUMNS + " WHERE sheet_id = ? ORDER BY position, id",
                People::person,
                sheetId);
        Map<Long, List<Long>> patrons = new HashMap<>();
        jdbc.query("SELECT person_id, patron_id FROM person_patron WHERE sheet_id = ? ORDER BY id",
                (ResultSet rs) -> {
                    patrons.computeIfAbsent(rs.getLong("person_id"), k -> new ArrayList<>()).add(rs.getLong("patron_id"));
                }, sheetId);
        Map<Long, TreeMap<LocalDate, String>> grades = new HashMap<>();
        jdbc.query("SELECT person_id, grade, from_date FROM person_grade WHERE sheet_id = ?",
                (ResultSet rs) -> {
                    grades.computeIfAbsent(rs.getLong("person_id"), k -> new TreeMap<>())
                            .put(fromKey(rs.getDate("from_date")), rs.getString("grade"));
                }, sheetId);
        Map<Long, List<Hold>> holds = new HashMap<>();
        jdbc.query("SELECT person_id, from_date, to_date FROM person_hold WHERE sheet_id = ? ORDER BY id",
                (ResultSet rs) -> {
                    holds.computeIfAbsent(rs.getLong("person_id"), k -> new ArrayList<>()).add(hold(rs));
                }, sheetId);
        Map<Long, List<String>> aliases = new HashMap<>();
        jdbc.query("SELECT person_id, alias FROM person_alias WHERE sheet_id = ? ORDER BY alias_key, id",
                (ResultSet rs) -> {
                    aliases.computeIfAbsent(rs.getLong("person_id"), k -> new ArrayList<>()).add(rs.getString("alias"));
                }, sheetId);
        java.util.Set<String> used = people.isEmpty() ? java.util.Set.of() : usedInTree(sheetId);
        for (Person person : people) {
            person.setAliases(aliases.getOrDefault(person.getId(), new ArrayList<>()));
            person.setHolds(holds.getOrDefault(person.getId(), new ArrayList<>()));
            person.setPatronIds(patrons.getOrDefault(person.getId(), new ArrayList<>()));
            TreeMap<LocalDate, String> dated = grades.get(person.getId());
            if (dated != null) person.setGrades(dated);
            person.setClashing(clashing(person, used));
        }
        return people;
    }

    /** The person with this id on this sheet, or null when there is none. */
    public Person find(String sheetId, long id) {
        return withPatrons(jdbc.query(COLUMNS + " WHERE sheet_id = ? AND id = ?",
                People::person,
                sheetId, id).stream().findFirst().orElse(null));
    }

    /** The person with this id on this sheet, read afresh and locked for the rest of the
     *  transaction, so two statements for one person at once happen one after the other. */
    public Person lock(String sheetId, long id) {
        return withPatrons(jdbc.query(COLUMNS + " WHERE sheet_id = ? AND id = ? FOR UPDATE", People::person, sheetId, id)

