-- The sheet a transferred person came from, and the name they had there (both null: the person
-- was not transferred here). The audit viewer follows a person's lines back to that sheet.
DROP TRIGGER public.person_history;
ALTER TABLE public.person ADD COLUMN origin_sheet VARCHAR(255);
ALTER TABLE public.person ADD COLUMN origin_name VARCHAR(255);
ALTER TABLE asof.person ADD COLUMN origin_sheet VARCHAR(255);
ALTER TABLE asof.person ADD COLUMN origin_name VARCHAR(255);
ALTER TABLE asof_hist.person ADD COLUMN origin_sheet VARCHAR(255);
ALTER TABLE asof_hist.person ADD COLUMN origin_name VARCHAR(255);
-- The history trigger keeps the column list it was created with: create it again to see the new ones.
CREATE TRIGGER person_history AFTER INSERT, UPDATE, DELETE ON public.person FOR EACH ROW CALL 'net.officefloor.hq.app.sheet.History';
-- A person's place in their sheet's list: the list (and every action that works in list order)
-- runs by ascending position. A new person goes to the end; moving a person up or down swaps their
-- position with their neighbour's. People already on a sheet keep the order they were added in.
DROP TRIGGER public.person_history;
ALTER TABLE public.person ADD COLUMN position BIGINT;
ALTER TABLE asof.person ADD COLUMN position BIGINT;
ALTER TABLE asof_hist.person ADD COLUMN position BIGINT;
UPDATE public.person SET position = id;
UPDATE asof_hist.person SET position = id;
CREATE INDEX person_sheet_position ON public.person (sheet_id, position);
-- The history trigger keeps the column list it was created with: create it again to see the new one.
CREATE TRIGGER person_history AFTER INSERT, UPDATE, DELETE ON public.person FOR EACH ROW CALL 'net.officefloor.hq.app.sheet.History';
-- A pool membership may carry a from-date and a to-date (both optional; the to-date not before the
-- from-date). A member whose dates do not include the sheet's today is left out of the pool.
DROP TRIGGER public.pool_member_history;
ALTER TABLE public.pool_member ADD COLUMN from_date DATE;
ALTER TABLE public.pool_member ADD COLUMN to_date DATE;
ALTER TABLE asof.pool_member ADD COLUMN from_date DATE;
ALTER TABLE asof.pool_member ADD COLUMN to_date DATE;
ALTER TABLE asof_hist.pool_member ADD COLUMN from_date DATE;
ALTER TABLE asof_hist.pool_member ADD COLUMN to_date DATE;
-- The history trigger keeps the column list it was created with: create it again to see the new ones.
CREATE TRIGGER pool_member_history AFTER INSERT, UPDATE, DELETE ON public.pool_member FOR EACH ROW CALL 'net.officefloor.hq.app.sheet.History';
-- A sheet as it stood at the end of a date: every change made while the sheet's today was on or
-- before it counts, every later one does not (see sheet.AsOf).
--
-- asof_hist.<table> keeps every row each change to <table> removed ('D') or added ('I'), with the
-- sheet's today when it was made (an update removes the old row and adds the new one). It is
-- written by the trigger sheet.History on each table of a sheet's data.
--
-- asof.<table> has the same columns as <table>: a sheet's rows as of a date are rebuilt into it, and
-- the app's own reads run against it in place of the live tables. A later migration that changes one
-- of these tables must change its asof and asof_hist copies the same way.
CREATE SCHEMA asof;
CREATE SCHEMA asof_hist;
CREATE SEQUENCE asof_hist.change_seq;
CREATE TABLE asof.sheet AS SELECT * FROM public.sheet WHERE FALSE;

CREATE TABLE asof.claim AS SELECT * FROM public.claim WHERE FALSE;
CREATE TABLE asof_hist.claim AS SELECT * FROM public.claim WHERE FALSE;
ALTER TABLE asof_hist.claim ADD COLUMN h_seq BIGINT NOT NULL;
ALTER TABLE asof_hist.claim ADD COLUMN h_made_on DATE;
ALTER TABLE asof_hist.claim ADD COLUMN h_op CHAR(1) NOT NULL;
CREATE INDEX claim_hist_sheet ON asof_hist.claim (sheet_id, h_seq);
CREATE TRIGGER claim_history AFTER INSERT, UPDATE, DELETE ON public.claim FOR EACH ROW CALL 'net.officefloor.hq.app.sheet.History';

CREATE TABLE asof.person AS SELECT * FROM public.person WHERE FALSE;
CREATE TABLE asof_hist.person AS SELECT * FROM public.person WHERE FALSE;
ALTER TABLE asof_hist.person ADD COLUMN h_seq BIGINT NOT NULL;
ALTER TABLE asof_hist.person ADD COLUMN h_made_on DATE;
ALTER TABLE asof_hist.person ADD COLUMN h_op CHAR(1) NOT NULL;
CREATE INDEX person_hist_sheet ON asof_hist.person (sheet_id, h_seq);
CREATE TRIGGER person_history AFTER INSERT, UPDATE, DELETE ON public.person FOR EACH ROW CALL 'net.officefloor.hq.app.sheet.History';

CREATE TABLE asof.person_grade AS SELECT * FROM public.person_grade WHERE FALSE;
CREATE TABLE asof_hist.person_grade AS SELECT * FROM public.person_grade WHERE FALSE;
ALTER TABLE asof_hist.person_grade ADD COLUMN h_seq BIGINT NOT NULL;
ALTER TABLE asof_hist.person_grade ADD COLUMN h_made_on DATE;
